  gap: clamp(0.3rem, 0.8vw, 0.5rem);
  z-index: 1000;
}
.dot {
  width: clamp(0.45rem, 0.8vw, 0.65rem);
  height: clamp(0.45rem, 0.8vw, 0.65rem);
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.12);
  cursor: pointer;
}
.dot.active { background: var(--accent); }

/* === TYPOGRAPHY === */
h1, h2, h3 { margin: 0; letter-spacing: -0.02em; }
.slide-title {
  font-size: clamp(1.2rem, 2.6vw, 2.35rem);
  line-height: 1.15;
  font-weight: 800;
  max-width: 95%;
}
.kicker {
  font-family: "IBM Plex Mono", monospace;
  font-size: clamp(0.66rem, 1vw, 0.9rem);
  color: var(--accent2);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.sub {
  color: var(--muted);
  font-size: clamp(0.8rem, 1.35vw, 1.05rem);
}

/* === LAYOUT HELPERS === */
.head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: var(--content-gap);
  margin-bottom: clamp(0.5rem, 1.5vw, 1rem);
}
.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: clamp(0.55rem, 1.2vw, 1rem);
  padding: clamp(0.45rem, 1.1vw, 0.95rem);
  backdrop-filter: blur(5px);
}

/* === TABLE === */
table {
  width: 100%;
  border-collapse: collapse;
  font-size: clamp(0.58rem, 0.9vw, 0.8rem);
}
th, td {
  padding: clamp(0.22rem, 0.5vw, 0.4rem) clamp(0.3rem, 0.6vw, 0.48rem);
  border-bottom: 1px solid var(--line);
  text-align: left;
}
th { color: var(--accent2); font-weight: 700; }

/* === BARS === */
.bar-wrap { display: grid; gap: clamp(0.2rem, 0.5vw, 0.33rem); }
.row {
  display: grid;
  grid-template-columns: 1.5fr 5fr 0.6fr;
  gap: clamp(0.25rem, 0.7vw, 0.45rem);
  align-items: center;
  font-size: clamp(0.56rem, 0.88vw, 0.78rem);
}
.row .name { color: #d8e4ff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.row .bar {
  height: clamp(0.45rem, 0.9vw, 0.72rem);
  border-radius: 999px;
  background: rgba(255,255,255,0.09);
  overflow: hidden;
}
.row .fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent), #9de8ff);
}
.row .score { font-family: "IBM Plex Mono", monospace; color: var(--accent2); }

/* === GRID === */
.grid-2 {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: clamp(0.5rem, 1vw, 0.9rem);
  min-height: 0;
}
.metric-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(0.35rem, 0.8vw, 0.6rem);
}
.metric {
  border: 1px solid var(--line);
  border-radius: clamp(0.45rem, 0.9vw, 0.7rem);
  padding: clamp(0.38rem, 0.7vw, 0.56rem);
  background: rgba(255,255,255,0.04);
}
.metric .n { font-size: clamp(0.8rem, 1.6vw, 1.3rem); font-weight: 800; }
.metric .l { font-size: clamp(0.56rem, 0.85vw, 0.72rem); color: var(--muted); }

/* === IMAGE === */
.scatter {
  width: 100%;
  max-height: min(46vh, 350px);
  border-radius: clamp(0.45rem, 0.9vw, 0.75rem);
  border: 1px solid var(--line);
}

/* === SIMPLE REVEAL === */
.reveal { opacity: 0; transform: translateY(12px); animation: rise 0.6s ease forwards; }
.reveal.d2 { animation-delay: 0.15s; }
.reveal.d3 { animation-delay: 0.28s; }
@keyframes rise { to { opacity: 1; transform: translateY(0); } }
  </style>
</head>
